    public function __construct($name)
    {
        // Parse the name and color if provided in the format 'iconName#color'
        if (strpos($name, '#') !== false) {
            list($this->name, $this->color) = explode('#', $name, 2);
        } else {
            $this->name = $name;
        }

        $this->name = str_replace(" ", "", $this->name); // Remove spaces
    }

    public static function make($name)
    {
        return new self($name);
    }

    public function class($class)
    {
        $this->class = $class;
        return $this;
    }

    public function type($type)
    {
        $this->type = $type; // Set the type (e.g., 'duotone')
        return $this;
    }

    public function show()
    {
        // Select the appropriate icon set based on the type
        $icons = ($this->type == 'duotone') ? self::$iconsDuotone[$this->name] : self::$icons[$this->name];
        if (!isset($icons)) {
            throw new Exception("Icon '{$this->name}' not found.");
        }
    
        $iconHtml = $icons;
    
        // Build the final class string
        $finalClass = '$1 ' . $this->class; // Append the custom class to the existing class
    
        // Build the inline style for color
        $style = '';
        if (!empty($this->color)) {
            $style = 'style="color:#' . htmlspecialchars($this->color) . ';"';
        }
    
        // Pattern to match the opening tag with the class attribute
        $pattern = '/(<[^>]*class="[^"]*)/';
    
        // Replacement string to add the new class and style
        $replacement = $finalClass . '" ' . $style;
    
        // Perform the replacement
        $result = preg_replace($pattern, $replacement, $iconHtml);
    
        echo $result;
    }
}
